import type { ResourceConfig } from '../../config/schema';
import { resourceScope } from '../../config/schema';

/**
 * 资料在列表里的呈现逻辑（纯函数，抽屉与档案页共用）。
 *
 * 排列依据（2026-10-09 按现场反馈调整）：挂靠资料**按类型分组**——
 * 先图片、再图纸（PDF 文档）、最后视频/模型，一类一组排好，
 * 组内仍按年代升序（没有年代的排在该组末尾，稳定排序保持策展顺序）。
 *
 * 为什么改掉了原来"按事件阶段分组"：那套是 DAM 式的"内容维度做组织、类型维度做筛选"，
 * 但在手机上翻一台设备的十几份资料时，使用者是**按要找的东西的类型**找的
 * （先扫图片、再看图纸、最后看影像），类型当一级结构比事件阶段好找。
 */

const KIND_LABELS: Record<ResourceConfig['kind'], string> = {
  image: '图片',
  video: '视频',
  // 中类统一叫「文档」：这批 PDF 里既有装置图纸，也有安装总结、名录通知，叫"图纸"不准确。
  pdf: '文档',
  model: '模型',
};

/** 秒 → `4:07`（时长角标）。 */
export function formatDuration(seconds: number) {
  const minutes = Math.floor(seconds / 60);
  const rest = Math.round(seconds % 60);
  return `${minutes}:${String(rest).padStart(2, '0')}`;
}

export interface CardVisual {
  /** 缩略图地址；空字符串 = 没有图，卡片用「纸张」占位 */
  thumb: string;
  /** 右下角角标：视频时长 `4:07` / 图纸页数 `56 页`；没有就不显示 */
  badge: string;
}

/**
 * 档案卡片的缩略图与角标（纯函数，便于单测）。
 *
 * 图从哪来：配置里的 `thumb`（`npm run thumbs` 生成的 540×405 小图，一屏 6 张不到 300 KB）→
 * 退而求其次用 `url`／`poster` 原图 → 都没有就返回空串，由页面显示"纸张"占位卡。
 * **不要**默认去拉原图：院方照片单张 400 KB 起步。
 */
export function cardVisual(resource: ResourceConfig): CardVisual {
  const thumb = resource.thumb ?? (resource.kind === 'image' ? resource.url : resource.poster ?? '');
  const badge = resource.kind === 'video' && resource.extent?.seconds
    ? formatDuration(resource.extent.seconds)
    : resource.kind === 'pdf' && resource.extent?.pages
      ? `${resource.extent.pages} 页`
      : '';
  return { thumb, badge };
}

/**
 * 标题里配置自带的「（1980 年）」拆出来单独渲染（灰色小字），别让它跟主名抢视觉。
 * 认不出就不拆——标题是院方给的名字，不做任何改写。
 */
export function splitTitle(title: string): { main: string; suffix: string } {
  const matched = /^(.*?)（(\d{4}) 年）$/.exec(title);
  return matched ? { main: matched[1]!, suffix: `（${matched[2]} 年）` } : { main: title, suffix: '' };
}

export interface ResourceBadge {
  /** 类型短名 */
  kind: string;
  /** 体量：`56 页` / `4:07` / `1980 年`（没有就不显示） */
  measure: string;
  /** 层级：项目/机构级资料会显示「项目级」——关系在设备上，层级不在设备上，必须显式标注 */
  scope: string;
}

/** 卡片上的徽标：类型 + 体量（页数/时长/年代）+ 层级。 */
export function resourceBadge(resource: ResourceConfig): ResourceBadge {
  const measure = resource.kind === 'pdf' && resource.extent?.pages
    ? `${resource.extent.pages} 页`
    : resource.kind === 'video' && resource.extent?.seconds
      ? formatDuration(resource.extent.seconds)
      : resource.period?.year === undefined ? '' : `${resource.period.year} 年`;
  return {
    kind: KIND_LABELS[resource.kind],
    measure,
    scope: resourceScope(resource) === 'program' ? '项目级' : '',
  };
}

/** 类型筛选选项：只列出这批资料里确实存在的类型，不产生点了没结果的空筛选项。 */
export function kindOptions(resources: ResourceConfig[]): Array<{ value: ResourceConfig['kind'] | 'all'; label: string }> {
  const present = new Set(resources.map(item => item.kind));
  // 顺序与分组顺序一致（图片 → 图纸 → 视频 → 模型），筛选项和下面组的先后对得上。
  return [
    { value: 'all', label: '全部' },
    ...KIND_ORDER.filter(kind => present.has(kind)).map(kind => ({ value: kind, label: KIND_LABELS[kind] })),
  ];
}

export interface ResourceGroup {
  key: string;
  label: string;
  items: ResourceConfig[];
}

/** 分组顺序：图片 → 图纸（PDF 文档）→ 视频 → 模型。 */
export const KIND_ORDER: Array<ResourceConfig['kind']> = ['image', 'pdf', 'video', 'model'];

const KIND_RANK = new Map(KIND_ORDER.map((kind, index) => [kind, index]));

/** 组内/平铺列表的次序：年代升序，没年代的排末尾（稳定排序，保持策展顺序）。 */
function byYear(left: ResourceConfig, right: ResourceConfig) {
  return (left.period?.year ?? Number.POSITIVE_INFINITY) - (right.period?.year ?? Number.POSITIVE_INFINITY);
}

/**
 * 平铺列表（档案页「总览」）的次序：**先按类型、同类里再按年代**。
 * 与抽屉的分组顺序同一套规则，全站扫下来是"图片 → 图纸 → 视频"的顺序。
 */
export function sortByKindThenYear(resources: ResourceConfig[]): ResourceConfig[] {
  return [...resources].sort((left, right) =>
    (KIND_RANK.get(left.kind) ?? KIND_ORDER.length) - (KIND_RANK.get(right.kind) ?? KIND_ORDER.length)
    || byYear(left, right));
}

/**
 * 按**类型**分组：一类一组，组的先后由 `KIND_ORDER` 决定，组内按年代升序。
 * 没有年代的（例如只有说明没有拍摄年的资料）排在该组末尾；不产生空组。
 */
export function groupResources(resources: ResourceConfig[]): ResourceGroup[] {
  return KIND_ORDER
    .map(kind => ({
      key: kind,
      label: KIND_LABELS[kind],
      items: resources.filter(item => item.kind === kind).sort(byYear),
    }))
    .filter(group => group.items.length > 0);
}
